-- Publish the eleventh verified 2026 batch: seven complete school-first study maps.
-- Facts come from the official 2026 charters and the official syllabus pages/files supplied by the user.
-- Draft rows are snapshotted and compared byte-for-byte before this transaction can commit.

create temporary table batch_eleven_protected_offering_drafts on commit drop as
select to_jsonb(o) as row_data from public.admission_offerings o where o.status = 'draft';

create temporary table batch_eleven_protected_point_drafts on commit drop as
select to_jsonb(p) as row_data from public.syllabus_points p where p.status = 'draft';

do $$
begin
  if (select count(*) from batch_eleven_protected_offering_drafts) <> 4 then
    raise exception 'Batch eleven stopped: expected 4 protected draft offerings';
  end if;
  if (select count(*) from batch_eleven_protected_point_drafts) <> 33 then
    raise exception 'Batch eleven stopped: expected 33 protected draft syllabus points';
  end if;
  if (select count(*) from public.admission_offerings where status = 'published') <> 67
     or (select count(*) from public.syllabus_points where status = 'published') <> 568
     or (select count(*) from public.resources where status = 'published') <> 58 then
    raise exception 'Batch eleven stopped: production baseline changed';
  end if;
  if exists (
    select 1 from public.admission_offerings where school_slug in
      ('anhui-school-16','anhui-school-17','anhui-school-18','anhui-school-19','anhui-school-24','anhui-school-25','anhui-school-30')
  ) or exists (
    select 1 from public.syllabus_points where school_slug in
      ('anhui-school-16','anhui-school-17','anhui-school-18','anhui-school-19','anhui-school-24','anhui-school-25','anhui-school-30')
  ) then
    raise exception 'Batch eleven stopped: placeholder school slugs already have academic content';
  end if;
end $$;

update public.academic_schools
set school_slug = case wall_school_id
    when 'anhui-school-16' then 'bzuu'
    when 'anhui-school-17' then 'chzu'
    when 'anhui-school-18' then 'ahszu'
    when 'anhui-school-19' then 'hsu'
    when 'anhui-school-24' then 'ahua'
    when 'anhui-school-25' then 'aycc'
    when 'anhui-school-30' then 'aisu'
  end,
  theme_color = case wall_school_id
    when 'anhui-school-16' then '#7A3E9D'
    when 'anhui-school-17' then '#1E6F5C'
    when 'anhui-school-18' then '#355C9A'
    when 'anhui-school-19' then '#2F6F4E'
    when 'anhui-school-24' then '#8A3D6D'
    when 'anhui-school-25' then '#28728C'
    when 'anhui-school-30' then '#C05A28'
  end
where wall_school_id in ('anhui-school-16','anhui-school-17','anhui-school-18','anhui-school-19','anhui-school-24','anhui-school-25','anhui-school-30');

-- A single school and campus can legitimately publish the same program in both
-- liberal-arts and science tracks. The exam scheme is the stable discriminator.
drop index if exists public.admission_offerings_scope_school_site_program_unique;
create unique index admission_offerings_scope_school_site_program_scheme_unique
on public.admission_offerings (
  year, province_slug, major_slug, school_slug, lower(btrim(training_site)), program_names,
  coalesce(exam_scheme_id, '')
);

