do $$
declare
  draft_offerings integer;
  draft_points integer;
begin
  select count(*) into draft_offerings from public.admission_offerings where status = 'draft';
  select count(*) into draft_points from public.syllabus_points where status = 'draft';
  if draft_offerings <> 4 or draft_points <> 33 then
    raise exception 'Batch eleven stopped: draft counts changed (% offerings, % points)', draft_offerings, draft_points;
  end if;
  if exists (
    (select row_data from batch_eleven_protected_offering_drafts except select to_jsonb(o) from public.admission_offerings o where o.status = 'draft')
    union all
    (select to_jsonb(o) from public.admission_offerings o where o.status = 'draft' except select row_data from batch_eleven_protected_offering_drafts)
  ) or exists (
    (select row_data from batch_eleven_protected_point_drafts except select to_jsonb(p) from public.syllabus_points p where p.status = 'draft')
    union all
    (select to_jsonb(p) from public.syllabus_points p where p.status = 'draft' except select row_data from batch_eleven_protected_point_drafts)
  ) then
    raise exception 'Batch eleven stopped: protected draft content changed';
  end if;
  if (select count(*) from public.admission_offerings where status = 'published') <> 132 then
    raise exception 'Batch eleven stopped: published offering count is not 132';
  end if;
  if (select count(distinct school_slug) from public.admission_offerings where status = 'published') <> 38 then
    raise exception 'Batch eleven stopped: complete school map count is not 38';
  end if;
  if (select count(*) from public.syllabus_points where status = 'published') <> 1033 then
    raise exception 'Batch eleven stopped: published syllabus point count is not 1033';
  end if;
  if (select count(*) from public.resources where status = 'published') <> 80 then
    raise exception 'Batch eleven stopped: published resource count is not 80';
  end if;
  if exists (
    select 1 from public.syllabus_points p
    where p.status = 'published'
      and not exists (
        select 1 from public.resources r
        where r.status = 'published' and p.canonical_topic = any(r.topic_tags)
      )
  ) then
    raise exception 'Batch eleven stopped: published syllabus points without resources';
  end if;
  if exists (
    select url from public.resources where status = 'published' group by url having count(*) > 1
  ) then
    raise exception 'Batch eleven stopped: duplicate published resource URL';
  end if;
  if exists (
    select 1 from public.admission_offerings
    where school_slug = 'anhui-school-29' and status = 'published'
  ) then
    raise exception 'Batch eleven stopped: Hefei City College must remain unpublished';
  end if;
  if (select count(*) from public.admission_offerings where year = 2027 and status = 'draft' and active = false) <> 4
     or exists (select 1 from public.admission_offerings where year = 2027 and status <> 'draft') then
    raise exception 'Batch eleven stopped: 2027 draft isolation changed';
  end if;
end $$;
